def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    h = max(0, int(horizon))
    if h == 0:
        return []
    try:
        x = np.asarray(list(history), dtype=float).reshape(-1)
    except Exception:
        return [0.0] * h
    if x.size == 0:
        return [0.0] * h
    finite = np.isfinite(x)
    if not finite.any():
        return [0.0] * h
    if not finite.all():
        good = np.flatnonzero(finite)
        x = np.interp(np.arange(x.size), good, x[good])
    cap = np.finfo(float).max / 1000000.0
    x = np.clip(x, -cap, cap)
    n = x.size
    f = str(frequency).lower()
    if 'hour' in f:
        p = 24
    elif 'quarter' in f:
        p = 4
    elif 'month' in f:
        p = 12
    elif 'week' in f:
        p = 52
    elif 'day' in f:
        p = 7
    else:
        p = max(2, min(24, n // 2))
    if n < p:
        level = float(np.median(x))
        return [level] * h
    start = max(0, n - 4 * p)
    global_level = float(np.median(x[start:]))
    template = np.empty(p, dtype=float)
    dispersion = np.empty(p, dtype=float)
    for phase in range(p):
        vals = np.asarray([x[i] for i in range(start, n) if i % p == phase], dtype=float)
        if vals.size:
            template[phase] = float(np.median(vals))
            dispersion[phase] = float(np.median(np.abs(vals - template[phase])))
        else:
            template[phase] = global_level
            dispersion[phase] = 0.0
    ranges = []
    complete = []
    for end in range(n, p - 1, -p):
        block = x[end - p:end]
        if block.size == p:
            complete.append(block)
            ranges.append(float(np.quantile(block, 0.9) - np.quantile(block, 0.1)))
        if len(complete) >= 4:
            break
    if len(complete) >= 2:
        recent_range = max(ranges[0], 1e-12)
        robust_range = max(float(np.median(ranges)), 1e-12)
        scale = float(np.sqrt(recent_range / robust_range))
        scale = float(np.clip(scale, 0.75, 1.25))
        recent_level = float(np.median(complete[0]))
        template = recent_level + scale * (template - float(np.median(template)))
    data_scale = max(float(np.quantile(x, 0.95) - np.quantile(x, 0.05)), 1.0)
    lower = float(np.min(x) - 0.5 * data_scale)
    upper = float(np.max(x) + 0.5 * data_scale)
    out = []
    for j in range(h):
        phase = (n + j) % p
        value = float(template[phase])
        if not np.isfinite(value):
            value = global_level
        out.append(float(np.clip(value, lower, upper)))
    return [float(np.clip(v, -cap, cap)) for v in out]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    h = max(0, int(horizon))
    if h == 0:
        return []
    try:
        x = np.asarray(list(history), dtype=float).reshape(-1)
    except Exception:
        return [0.0] * h
    if x.size == 0:
        return [0.0] * h
    finite = np.isfinite(x)
    if not finite.any():
        return [0.0] * h
    if not finite.all():
        good = np.flatnonzero(finite)
        x = np.interp(np.arange(x.size), good, x[good])
    cap = np.finfo(float).max / 1000000.0
    x = np.clip(x, -cap, cap)
    n = x.size
    f = str(frequency).lower()
    if 'hour' in f:
        p = 24
    elif 'quarter' in f:
        p = 4
    elif 'month' in f:
        p = 12
    elif 'week' in f:
        p = 52
    elif 'day' in f:
        p = 7
    else:
        p = max(2, min(24, n // 2))
    baseline = float(np.quantile(x, 0.1))
    span = float(np.quantile(x, 0.95) - baseline)
    if span <= 1e-12:
        return [baseline] * h
    threshold = baseline + 0.08 * span
    active = x > threshold
    onsets = [i for i in range(n) if active[i] and (i == 0 or not active[i - 1])]
    clean = []
    for onset in onsets:
        if not clean or onset - clean[-1] >= max(2, p // 3):
            clean.append(onset)
    onsets = clean
    if len(onsets) < 2:
        if n >= p:
            return [float(np.clip(x[n - p + (j % p)], -cap, cap)) for j in range(h)]
        return [float(np.median(x))] * h
    gaps = np.diff(np.asarray(onsets, dtype=int))
    interval = max(2, int(round(float(np.median(gaps)))))
    interval = int(np.clip(interval, max(2, p // 2), max(p * 2, 2)))
    shapes = []
    for onset in onsets:
        end = min(n, onset + interval)
        segment = np.full(interval, baseline, dtype=float)
        segment[:end - onset] = x[onset:end]
        if end - onset >= max(2, interval // 3):
            shapes.append(segment)
    if not shapes:
        return [baseline] * h
    shape = np.median(np.vstack(shapes[-4:]), axis=0)
    peaks = np.asarray([np.max(s) - baseline for s in shapes[-4:]], dtype=float)
    robust_peak = max(float(np.median(peaks)), 1e-12)
    recent_peak = max(float(peaks[-1]), 0.0)
    amplitude = float(np.clip(np.sqrt(max(recent_peak, 1e-12) / robust_peak), 0.75, 1.25))
    shape = baseline + amplitude * (shape - baseline)
    next_onset = onsets[-1] + interval
    while next_onset < n:
        next_onset += interval
    lower = float(min(np.min(x), baseline))
    upper = float(np.max(x) + 0.25 * span)
    out = []
    for j in range(h):
        t = n + j
        offset = t - next_onset
        if 0 <= offset < interval:
            value = float(shape[offset])
        else:
            value = baseline
        out.append(float(np.clip(value, lower, upper)) if np.isfinite(value) else baseline)
    return [float(np.clip(v, -cap, cap)) for v in out]
